import Link from "next/link";
import { formatDate } from "../../../lib/portfolio/utils";
import type { BlogPost } from "../../../lib/portfolio/notion/blog";

type BlogPostCardProps = {
  post: BlogPost;
  featured?: boolean;
  priority?: boolean;
};

export function BlogPostCard({ post, featured = false, priority = false }: Readonly<BlogPostCardProps>) {

  return (
    <Link
      href={`/blog/${post.slug}`}
      className="block group h-full border group transition-colors duration-normal   hover:bg-white/2 p-6 border-border hover:border-primary/50"
    >
      <article className="flex flex-col h-full justify-between">
        <div
          className={`flex items-center gap-2 mb-6 border-b pb-4 border-zinc-900`}
        >
          <div className="flex gap-1.5 ">
            <div className="w-2 h-2 bg-primary"></div>
            <div className="w-2 h-2 bg-zinc-500"></div>
            <div className="w-2 h-2 bg-zinc-700"></div>
          </div>
        </div>

        <div className="flex-1">
          <div className="flex font-mono text-sm mr-auto items-center gap-4 text-foreground-muted mb-3 opacity-40 max-w-4xl">
            {post.publishedDate && (
              <time dateTime={post.publishedDate}>
                {formatDate(post.publishedDate)}
              </time>
            )}
            {post.readingTime > 0 && (
              <>
                <span>•</span>
                <span>{post.readingTime} min read</span>
              </>
            )}
          </div>
          <h3 className="text-3xl group-hover:text-primary font-bold text-foreground transition-colors duration-normal tracking-tight">
            {post.title}
          </h3>
          <p className="text-sm md:text-base text-foreground-secondary leading-relaxed group-hover:text-foreground transition-colors duration-normal mt-4 max-w-3xl font-light">
            {post.excerpt}
          </p>
        </div>

        <div className="  gap-4 pt-6 mt-2 border-t border-zinc-900/60">
          <div className="flex flex-wrap gap-2" aria-label="Tags">
            {post.tags.slice(0, 3).map((tag) => (
              <span
                key={tag}
                className="bg-zinc-900/60 text-zinc-400 group-hover:text-zinc-300 px-3 py-1 border border-zinc-800 group-hover:border-zinc-700/80 text-[10px] font-mono uppercase tracking-widest transition-all duration-300 "
              >
                {tag}
              </span>
            ))}
          </div>
        </div>
      </article>
    </Link>
  );
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}

import { cacheLife, cacheTag } from "next/cache";
import { Notionclient } from "./client";

export interface BlogPost {
  id: string;
  title: string;
  slug: string;
  content: string;
  excerpt: string;
  publishedDate: string;
  featured: boolean;
  readingTime: number;
  tags: string[];
  image?: string;
  createdby: string;
  createdByAvatar?: string;
}

export async function getBlogPostMarkdown(pageId: string): Promise<string> {
  "use cache";
  try {
    const response: any = await Notionclient.pages.retrieveMarkdown({
      page_id: pageId,
    });

    return response?.markdown || "";
  } catch (error) {
    console.error("Failed to load blog markdown from Notion:", error);
    return "";
  }
}

type NotionProperty = {
  type?: string;
  title?: Array<{ plain_text?: string }>;
  rich_text?: Array<{ plain_text?: string }>;
  multi_select?: Array<{ name?: string }>;
  checkbox?: boolean;
  number?: number;
  date?: { start?: string };
  files?: Array<{ file?: { url?: string }; external?: { url?: string } }>;
  created_by?: { name?: string; avatar_url?: string };
};

function getPlainText(prop?: NotionProperty): string {
  if (!prop) return "";
  if (prop.type === "title") return prop.title?.[0]?.plain_text || "";
  if (prop.type === "rich_text") return prop.rich_text?.[0]?.plain_text || "";
  return "";
}

function getTags(prop?: NotionProperty): string[] {
  if (prop?.type !== "multi_select") return [];
  return (prop.multi_select || []).map((tag) => tag.name || "").filter(Boolean);
}

function getImageUrl(prop?: NotionProperty): string | undefined {
  if (prop?.type !== "files") return undefined;
  const file = prop.files?.[0];
  return file?.file?.url || file?.external?.url;
}

function extractImageFromCover(row: any): string | undefined {
  if (row?.cover?.external?.url) return row.cover.external.url;
  if (row?.cover?.file?.url) return row.cover.file.url;
  return undefined;
}

function normalizeSlug(s: string | undefined): string {
  if (!s) return "";
  return s
    .toLowerCase()
    .replace(/\.+/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export async function getBlogPosts(dataSourceId?: string): Promise<BlogPost[]> {
  "use cache";
  cacheLife("hours");
  cacheTag("blog-posts");

  const sourceId =
    dataSourceId ||
    process.env.NOTION_BLOG_DATA_SOURCE_ID ||
    "aac5bb60-5924-4ace-8f77-af7f5fd5e715";

  if (!sourceId) {
    console.warn("No Notion blog data source ID configured");
    return [];
  }

  try {
    const allResults: any[] = [];
    let start_cursor: string | undefined = undefined;

    do {
      const resp: any = await Notionclient.request({
        path: `data_sources/${sourceId}/query`,
        method: "post",
        body: {
          page_size: 100,
          start_cursor,
        },
      });

      allResults.push(...(resp?.results || []));
      start_cursor = resp?.has_more ? resp?.next_cursor : undefined;
    } while (start_cursor);

    return allResults
      .map((row: any) => {
        const props = (row?.properties || {}) as Record<string, NotionProperty>;

        return {
          id: row.id,
          title: getPlainText(props.Title) || "Untitled",
          slug:
            normalizeSlug(getPlainText(props.Slug)) ||
            normalizeSlug(getPlainText(props.Title)) ||
            "",
          content: getPlainText(props.Excerpt) || "",
          excerpt: getPlainText(props.Excerpt) || "",
          publishedDate: props["Published Date"]?.date?.start || "",
          featured: !!props.Featured?.checkbox,
          createdby: props["Written by"]?.created_by?.name || "Unknown",
          createdByAvatar: props["Written by"]?.created_by?.avatar_url,
          readingTime:
            typeof props["Reading Time"]?.number === "number"
              ? props["Reading Time"].number
              : 0,
          tags: getTags(props.Tags),
          image:
            getImageUrl(props["Files & media"]) || extractImageFromCover(row),
        };
      })
      .filter((post) => post.title && post.slug)
      .sort(
        (a, b) =>
          new Date(b.publishedDate).getTime() -
          new Date(a.publishedDate).getTime(),
      );
  } catch (error) {
    console.error("Failed to load blog posts from Notion:", error);
    return [];
  }
}

export async function getBlogPostBySlug(
  slug: string,
  dataSourceId?: string,
): Promise<BlogPost | null> {
  const posts = await getBlogPosts(dataSourceId);
  const target = normalizeSlug(slug);
  const post =
    posts.find((post) => normalizeSlug(post.slug) === target) || null;

  if (!post) return null;

  const markdown = await getBlogPostMarkdown(post.id);
  const contentWithoutTitle = markdown.replace(/^#\s+.+\n?/, "").trimStart();

  return {
    ...post,
    content: contentWithoutTitle,
  };
}

import { Client } from "@notionhq/client";

const token = process.env.NOTION_SECRET || process.env.NOTION_API_KEY;

export const Notionclient = new Client({ auth: token });

export { cn } from "cn"

export const currentYear = new Date().getFullYear().toString();
export function formatDate(date: string | Date): string {
  const dateObj = typeof date === "string" ? new Date(date) : date
  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(dateObj)
}
